"""Scoped answers to the 2 November supplied Trends queries."""
from azeroth_survivors_content import SOURCES,ref,a,ext,para,table,steps

def apply_keywords(pages):
 SOURCES['luck130']=('https://wow.aethus.pl/','Aethus · original Luck tooltip','Original v0.130.0 / e7d9dd47 English snapshot captured 30 October, re-read 2 November 2026: Run Stats Luck description, percentage templates and Gnome racial text. Single primary source; no rarity-roll formula or controlled run test. Screenshot is the dated Rewards menu, not a Luck measurement.')
 SOURCES['luckyodds']=('https://github.com/cadoky/LuckyOdds','Cadoky · LuckyOdds','Author README read 2 November 2026. The author describes the odds as approximate. Not installed or tested for compatibility here; its model is not a verified game formula.')
 SOURCES['github_package']=('https://github.com/myslithell/azeroth-survivors','myslithell · community desktop package','README read 2 November 2026: describes an Electron package of the browser build for Apple Silicon. Author claims only; executable, signing, security and save compatibility not tested by this site.')
 for d in pages:
  if d['slug'] in ['download-platforms/','items/','save-backup/']:
   d['review_note']=d.get('review_note','Earlier sections retain their stated version scope')+' · Source/keyword clarification added 2 November 2026; not a new gameplay test'
  if d['slug']=='download-platforms/':
   d['parts'] += [('source-safety','Is Azeroth Survivors safe? Check the specific source',para('Start at '+ext('https://wow.aethus.pl/','Aethus · original host')+' and use its own Windows link. This identifies the creator-linked route; it is not a malware audit or a guarantee about every future archive. Checked 2 November 2026. '+ref('launcher'))+table(['Result you found','What it actually is','Decision'],[['wow.aethus.pl','The original browser host and creator-linked Windows route.','Use this to establish which game/build you intended.'],['OutThisLife/azeroth-survivors-re','A separate Rust/Bevy reconstruction.','Use its README and data requirements; do not assume original saves, addon APIs or build advice apply. '+ref('rebuild')],['myslithell/azeroth-survivors','A community repository describing a macOS Electron package.','A GitHub listing alone does not establish creator endorsement, binary safety or current patch parity. '+ref('github_package')],['A similarly named play or download page','Potentially another provider, package or game.','Identify the actual frame/download host and version before moving progress.']])+para('We have not audited these binaries. A filename, star count or HTTPS address cannot establish that two packages contain the same game. Keep the browser/profile with your old progress and '+a('save-backup/','export before changing provider')+'.'))]
  if d['slug']=='items/':
   d['parts'].append(('luck','What does Luck change?',para('The inspected original Run Stats description ties Luck to the rarity of future level-up offers. It does not establish extra critical chance or a boss-gear drop multiplier. '+a('luck/','Compare Luck with immediate damage and rerolls')+ref('luck130'))))
  if d['slug']=='save-backup/':
   d['parts'].append(('cheat-engine','Cheat Engine tables and edited saves',para('No Cheat Engine table or save editor has been validated by this site for the original current build. Browser, downloaded original and community reconstruction are separate targets; a table labelled only “Azeroth Survivors” does not establish compatibility. This is a compatibility limit, not evidence that every memory editor fails.')+para('The built-in export/import path above preserves a portable copy; importing replaces the destination rather than merging progress. Keep untouched exports of both sides before trying third-party tools. A working import does not verify the contents of an edited file. '+ref('saves'))))
 pages.append(dict(id='AZK24',slug='luck/',title='Azeroth Survivors Luck: Effects & Upgrade Choices',h1='What does Luck do in Azeroth Survivors?',desc='Understand Luck in Azeroth Survivors: rarer upgrade offers, Gnome bonuses, immediate damage trade-offs and the limits of addon odds estimates.',review_note='Reviewed 2 November 2026 · Original v0.130.0 tooltip snapshot; current racial reference linked separately · No rarity-roll experiment',answer='Luck improves the chance of rarer upgrades when you level up, according to the original Run Stats description. It is a choice about future offers: compare it with damage, coverage or recovery that can solve the current fight. No exact rarity formula is verified here.'+ref('luck130'),parts=[
 ('choose','Luck or something that helps right now?',table(['Situation','Compare first','Reason'],[['The present wave is ending the run','A relevant damage, coverage or survival upgrade','A better future offer cannot help if you do not reach it.'],['Your engine works and you expect more levels','Luck versus the actual alternative','More future offers give the rarity benefit opportunities to matter; no fixed best minute is established.'],['You need a particular spell now','The current offer and available rerolls','Rarity and getting the required spell are different questions.'],['You need critical hits for a talent','Critical chance and that talent’s trigger','The Luck tooltip does not establish extra critical chance.'],['You want permanent boss equipment','The piece’s drop source and difficulty requirements','The inspected Luck tooltip does not establish a boss-loot multiplier.']])+para('This is editorial decision help from the tooltip’s scope, not a tested priority ranking. '+ref('luck130'))),
 ('sources-of-luck','Read the displayed bonus before changing race or talents',para('Gnome’s Engineering Specialization states +20% luck in the inspected original text. Race availability and unlocking it are separate from choosing an upgrade during a run. '+a('best-race/#live-races','Read the automatically checked racial values')+ref('luck130'))+para('The original snapshot also contains rank-dependent Luck percentage descriptions. Read the actual allocated talent or offered item for its value; do not substitute the unresolved template with a guessed percentage. A racial bonus, a talent and a run item can have different persistence rules. The Rewards screenshot shows the race-unlock location, not your current total or an observed rarity outcome.')),
 ('compare','Compare a Luck choice without inventing a drop rate',steps(['Record host, client version, class, race and permanent talents.','Inspect the current Luck entry in Run Stats; preserve the displayed value and the chosen offer.','Compare otherwise similar attempts and record level-up rarities, not just a memorable legendary.','Keep upgrade-card outcomes separate from boss gear and critical-hit counts.','Treat a small sample as an observation, not proof of a percentage-per-point formula.'])+para('No controlled sample is supplied on this page. '+ref('luck130'))),
 ('addon','Does LuckyOdds reveal the exact formula?',para('Cadoky’s LuckyOdds offers an odds panel and minimap helpers. Its author explicitly presents the odds as a rough guide rather than the exact game roll. That makes it an optional display to compare, not evidence for a precise probability calculator on this page. '+ref('luckyodds'))+para('Use '+ext('https://github.com/cadoky/LuckyOdds','GitHub · LuckyOdds author project')+' for the current release and requirements; '+a('addons/','choose the browser or desktop installation path')+'. We have not installed it or checked compatibility with the latest original build.'))],related=[('items/','Compare jewelry by function'),('best-race/','Check racial benefits'),('builds/','Choose a working damage engine')]))
 return pages
